-- hololive production 成員名冊（含畢業）。由 scripts/build-agency-rosters.mjs 產生，不要手改。
-- 來源：scripts/data/hololive-roster-2026-09.json（2026-09-30 逐分部查證，每位成員附官網或 COVER 公告出處）
-- 依賴：20260930130000（hololive production 頂層團體）、20260929120000（graduated_at／former_group_id／is_official）
-- 部署順序：本檔 → Edge Function → 前端；避開排程時段。
-- **須單一交易套用**（apply_migration 或 psql -1）：回滾靠 created_at＝交易開始時間辨識本檔新增的頻道。
-- 重新套用前先 drop 第 0 段的 backup 表（第 0 段偵測到舊備份會直接中止）。
-- 正式站套用前先確認既有成員 id 都在：本檔第 2 段的 v.id 清單 select count(*) 應等於第 2 段筆數（id 取自本地匯出的正式站資料）。
-- 回滾（依第 0 段備份）：
--   delete from public.vtubers where contributed_by = 'research:hololive-2026-09';
--   delete from public.vtuber_channels c where c.created_at = (select applied_at from backup.rosters_meta_hololive_20260930) and not exists (select 1 from backup.vtuber_channels_ids_hololive_20260930 b where b.id = c.id);
--   update public.vtubers v set group_id = b.group_id, former_group_id = b.former_group_id, is_official = b.is_official, activity = b.activity, graduated_at = b.graduated_at,
--     debut_date = b.debut_date, youtube_channel_id = b.youtube_channel_id, twitch_channel_id = b.twitch_channel_id from backup.vtubers_rosters_hololive_20260930 b where b.id = v.id;
--   delete from public.vtuber_groups g where not exists (select 1 from backup.vtuber_groups_rosters_hololive_20260930 b where b.id = g.id);
--   update public.vtuber_groups g set kind = b.kind, parent_id = b.parent_id, verified_at = b.verified_at, note = b.note, member_count = b.member_count
--     from backup.vtuber_groups_rosters_hololive_20260930 b where b.id = g.id;

-- ===== 0. 套用前備份（回滾用；backup schema 不經 PostgREST 對外）=====
do $$ begin if to_regclass('backup.rosters_meta_hololive_20260930') is not null then raise exception '已有 backup.rosters_meta_hololive_20260930：確認後 drop 第 0 段的 backup 表再重新套用'; end if; end $$;
create schema if not exists backup;
revoke all on schema backup from public, anon, authenticated;
create table if not exists backup.vtubers_rosters_hololive_20260930 as select id, group_id, former_group_id, is_official, activity, graduated_at, debut_date, youtube_channel_id, twitch_channel_id from public.vtubers;
create table if not exists backup.vtuber_groups_rosters_hololive_20260930 as select * from public.vtuber_groups;
create table if not exists backup.vtuber_channels_ids_hololive_20260930 as select id from public.vtuber_channels;
create table if not exists backup.rosters_meta_hololive_20260930 as select now() as applied_at;

